import React, { useContext, useState } from 'react';
import { TripContext } from '../context/TripContext';

const AddExpense = () => {
  const { families, setExpenses } = useContext(TripContext);
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [paidBy, setPaidBy] = useState('');

  const handleAddExpense = (e) => {
    e.preventDefault();
    setExpenses(prev => [...prev, { description, amount: Number(amount), paidBy }]);
    setDescription('');
    setAmount('');
    setPaidBy('');
  };

  return (
    <form onSubmit={handleAddExpense} style={{ marginBottom: '20px' }}>
      <h3>Add Expense</h3>
      <input
        type="text"
        placeholder="Description"
        value={description}
        onChange={(e) => setDescription(e.target.value)}
        required
        style={{ marginRight: '10px' }}
      />
      <input
        type="number"
        placeholder="Amount"
        value={amount}
        onChange={(e) => setAmount(e.target.value)}
        required
        style={{ marginRight: '10px', width: '120px' }}
      />
      <select
        value={paidBy}
        onChange={(e) => setPaidBy(e.target.value)}
        required
        style={{ marginRight: '10px' }}
      >
        <option value="">Paid By</option>
        {families.map((f, i) => (
          <option key={i} value={f.familyName}>{f.familyName}</option>
        ))}
      </select>
      <button type="submit">Add</button>
    </form>
  );
};

export default AddExpense;
